\set ON_ERROR_STOP on
begin;
set local role authenticated; set local request.jwt.claims='{"sub":"30000000-0000-0000-0000-000000000003","role":"authenticated"}';
do $$ begin if (select count(*) from public.daily_attendance_results)<>1 then raise exception 'Staff self-only attendance RLS failed'; end if; if public.has_permission('attendance.adjust') then raise exception 'Staff adjustment authority drift'; end if; end $$;
reset role; set local role authenticated; set local request.jwt.claims='{"sub":"30000000-0000-0000-0000-000000000001","role":"authenticated"}';
do $$ begin if public.can_access_company_branch('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000002') then raise exception 'Supervisor unrelated outlet access'; end if; if public.has_permission('schedule.approve') then raise exception 'Supervisor Manager authority drift'; end if; end $$;
reset role; set local role authenticated; set local request.jwt.claims='{"sub":"30000000-0000-0000-0000-000000000004","role":"authenticated"}';
do $$ begin if public.has_permission('schedule.approve') then raise exception 'People schedule approval drift'; end if; if not public.has_permission('attendance.adjust') then raise exception 'People attendance authority missing'; end if; end $$;
reset role;
rollback;
